#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeEditorLienzo: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = EditorLienzo

    public static func lift(_ handle: UInt64) throws -> EditorLienzo {
        return EditorLienzo(unsafeFromHandle: handle)
    }

    public static func lower(_ value: EditorLienzo) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> EditorLienzo {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: EditorLienzo, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeEditorLienzo_lift(_ handle: UInt64) throws -> EditorLienzo {
    return try FfiConverterTypeEditorLienzo.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeEditorLienzo_lower(_ value: EditorLienzo) -> UInt64 {
    return FfiConverterTypeEditorLienzo.lower(value)
}






/**
 * **Un puerto escuchando.** Swift deja unos pocos hilos (4) esperando en
 * [`Escucha::atender`] (bloquea sin gastar nada hasta que alguien llama) y
 * cada uno la vuelve a llamar al terminar. Lo publica en Bonjour con
 * [`Escucha::puerto`].
 */
public protocol EscuchaProtocol: AnyObject, Sendable {
    
    /**
     * Como [`Escucha::atender_una`], pero dice **a quien** se atendio: una
     * sonda (no cambia nada: no hay que releer los chats), un aparato que
     * saludo (sincronizo o se unio: puede haber chats nuevos), una persona
     * de un chat compartido o archivos sueltos que llegaron. Asi Swift no
     * relee la lista cada vez que la presencia de Windows pregunta.
     *
     * Se puede llamar desde varios hilos a la vez sobre la misma
     * `Escucha`: cada uno atiende una conexion.
     */
    func atender() throws  -> Atendido
    
    /**
     * Espera a que llegue alguien y lo atiende entero: una sonda (`PING`),
     * alguien que se une al grupo o una vuelta de sincronizar. Devuelve
     * `false` si se cerro con [`Escucha::cerrar`] en vez de llegar nadie.
     */
    func atenderUna() throws  -> Bool
    
    /**
     * Deja de escuchar: **todas** las `atender` que esten esperando vuelven
     * con `Cerrada` (o `false`). Se despiertan conectandose a si mismo, una
     * vez por hilo que espera, que es lo unico que saca a un `accept` de su
     * espera sin sondear.
     */
    func cerrar() 
    
    /**
     * El puerto donde escucha de verdad (el que dio el sistema si se pidio 0).
     */
    func puerto()  -> UInt16
    
}
/**
 * **Un puerto escuchando.** Swift deja unos pocos hilos (4) esperando en
 * [`Escucha::atender`] (bloquea sin gastar nada hasta que alguien llama) y
 * cada uno la vuelve a llamar al terminar. Lo publica en Bonjour con
 * [`Escucha::puerto`].
 */
open class Escucha: EscuchaProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_pixpin_nucleo_fn_clone_escucha(self.handle, $0) }
    }
