/**
 * **Una carpeta de datos de PixPin abierta**: el objeto con el que trabaja
 * Swift. Es barato de crear y se puede usar desde varios hilos.
 */
public protocol NucleoProtocol: AnyObject, Sendable {
    
    /**
     * Quien es este aparato y en que grupo esta.
     */
    func aparato() throws  -> InfoAparato
    
    /**
     * La carpeta de datos.
     */
    func raiz()  -> String
    
    /**
     * Suelta las caches (indices de los cuadernos). Para el aviso de
     * memoria del sistema (`didReceiveMemoryWarning`,
     * `DispatchSource.makeMemoryPressureSource`): se rehacen solas al
     * volver a leer.
     */
    func vaciarCaches() 
    
    /**
     * **Adjunta un fichero a un chat**: lo copia dentro del proyecto y
     * escribe su mensaje (`IMAGEN` si es una foto, `VOZ` si es audio,
     * `ARCHIVO` lo demas), como al soltarlo en el chat de Windows.
     *
     * `nombre` es el que se ensena y con el que se guarda; sin el, el del
     * fichero de origen. Es bloqueante (copia el fichero): Swift lo llama
     * fuera del hilo principal.
     */
    func adjuntar(chat: String, rutaOrigen: String, nombre: String?) throws  -> MensajeChat
    
    /**
     * Las fotos de un lienzo del chat con su ruta **absoluta**, todas en
     * una llamada (no una por foto). Las que no se pueden resolver en este
     * aparato no salen.
     */
    func imagenesDelLienzo(chat: String, lienzo: Lienzo) throws  -> [ImagenDelLienzo]
    
    /**
     * La ruta absoluta del fichero de un mensaje (su `ruta`) o de una foto
     * de un lienzo, para ensenarlo o abrirlo. No comprueba que exista:
     * para eso basta mirar el disco desde Swift.
     */
    func rutaAbsoluta(chat: String, rutaRelativa: String) throws  -> String
    
    /**
     * Los ajustes de `pixpinmax.toml` (los de fabrica si no hay fichero).
     */
    func ajustes() throws  -> AjustesMac
    
    /**
     * Guarda los ajustes del Mac en `pixpinmax.toml` sin tocar lo demas.
     */
    func guardarAjustes(nuevos: AjustesMac) throws 
    
    /**
     * La ruta de `pixpinmax.toml` (para ensenarla).
     */
    func rutaAjustes()  -> String
    
    /**
     * Los ajustes `[pdf]` de `pixpinmax.toml`.
     */
    func ajustesPdf() throws  -> AjustesPdf
    
    /**
     * **Aligera un PDF del chat en su sitio** (`ruta`: la de
     * [`Nucleo::ruta_absoluta`]), como Windows. `a_mano`: pedido desde el
     * menu del mensaje (se repite aunque ya se hubiera pasado). Bloqueante.
     */
    func aligerarEnSuSitio(ruta: String, nivel: NivelAligerar, aMano: Bool, avance: AvanceAligerar)  -> DesenlaceAligerar
    
    /**
     * Guarda `[pdf]` sin tocar lo demas del fichero.
     */
    func guardarAjustesPdf(nuevos: AjustesPdf) throws 
    
    /**
     * **Busca en todo**: primero los chats por su nombre, luego los
     * mensajes y tareas de cada chat (el chat mas reciente primero y,
     * dentro, el mensaje mas nuevo primero) y al final los momentos del
     * timeline. Por paginas: `desde` y `cuantos`, hasta
     * [`TOPE_DE_RESULTADOS`]. Con `busqueda`, se puede cancelar desde otro
     * hilo. Una consulta sin palabras da una pagina vacia.
     */
    func buscar(consulta: String, desde: UInt32, cuantos: UInt32, busqueda: Busqueda?) throws  -> PaginaBusqueda
    
    /**
     * «Mensajes guardados», creandolo si no esta.
     */
    func chatGuardados() throws  -> FichaChat
    
    /**
     * Los chats, en el orden de la lista (lo ultimo tocado arriba y
     * «Mensajes guardados» primero). Es el indice, pequeno: no se abre
     * ningun proyecto.
     */
    func chats() throws  -> [FichaChat]
    
    /**
     * Crea un chat vacio. No crea su carpeta: eso lo hace el primer
     * mensaje, como en Windows.
     */
    func crearChat(nombre: String) throws  -> FichaChat
    
    /**
     * Escribe una nota en un chat: **una linea al final** de su cuaderno,
     * sellada con el codigo de este aparato y el siguiente numero, y sube
     * el chat en la lista. Igual que la caja de escribir de Windows
     * (`ventana_chat::escribir_nota`).
     */
    func escribirNota(chat: String, texto: String, respondeA: String?) throws  -> MensajeChat
    
    /**
     * Una pagina de mensajes contando desde el mas antiguo: `desde` es la
     * posicion del primero (0 el mas antiguo) y `cuantos` el largo (hasta
     * [`TOPE_DE_PAGINA`]). Un chat sin nada escrito da una pagina vacia.
     */
    func mensajes(chat: String, desde: UInt64, cuantos: UInt32) throws  -> PaginaMensajes
    
    /**
     * La ultima pagina: los `cuantos` mensajes mas nuevos. Es la que se pide
     * al abrir un chat; las anteriores, con [`Nucleo::mensajes`] y el
     * `desde` de esta.
     */
    func ultimosMensajes(chat: String, cuantos: UInt32) throws  -> PaginaMensajes
    
    /**
     * El chat compartido de la ficha `ficha` (`FichaChat.id`), si lo esta.
     */
    func chatCompartido(ficha: String) throws  -> ChatCompartidoMac?
    
    /**
     * Todos los chats compartidos que conoce este aparato.
     */
    func chatsCompartidos() throws  -> [ChatCompartidoMac]
    
    /**
     * **Comparte el chat** de la ficha `ficha` con personas (si ya lo
     * estaba, no cambia nada).
     */
    func compartirChat(ficha: String) throws  -> ChatCompartidoMac
    
    /**
     * **Entra en un chat compartido** con el `codigo` de quien invita, que
     * escucha en `host:puerto` (del QR, o buscado en Bonjour por la
     * etiqueta), y **se trae el chat**. Bloquea hasta terminar.
     */
    func entrarEnChatCompartido(codigo: String, host: String, puerto: UInt16) throws  -> ChatCompartidoMac
    
    /**
     * Si este aparato esta dentro de algun chat compartido: entonces hay
     * que escuchar y anunciarse aunque no haya grupo
     * ([`Nucleo::anuncio_de_presencia`]).
     */
    func hayChatsCompartidos() throws  -> Bool
    
    /**
     * **Abre la puerta para invitar** al chat de la ficha `ficha` (que
     * tiene que estar compartido): un codigo nuevo y un puerto propio
     * (IPv6 con IPv4 dentro) mientras la ventana este delante.
     */
    func invitarAChat(ficha: String) throws  -> Invitacion
    
    /**
     * El nombre con el que me ven en los chats compartidos (el del aparato
     * si no puse otro).
     */
    func nombreEnCompartidos() throws  -> String
    
    /**
     * Pone ese nombre (40 letras como mucho).
     */
    func ponerNombreEnCompartidos(nombre: String) throws 
    
    /**
     * **Quita a `id`** del chat compartido `chat` (el id que viaja), o
     * **sale** si `id` es este aparato. Solo quien lo creo quita a otros.
     */
    func quitarDeChatCompartido(chat: String, id: String) throws  -> ChatCompartidoMac
    
    /**
     * **Una vuelta con una persona** que escucha en `host:puerto`: se
     * juntan las listas de los chats que compartimos y cada chat donde
     * estamos los dos (nada mas: la valla). `id`, el de su aparato si se
     * sabe (comprueba que contesta quien debe); `chats`, solo esos (ids que
     * viajan) o todos los comunes si va vacio.
     */
    func sincronizarConPersona(host: String, puerto: UInt16, id: String?, chats: [String]) throws  -> ResumenPersona
    
    /**
     * **Abre la tinta de la hoja `pagina`** (desde 0) de `documento` para
     * verla y anotarla, en las unidades de la hoja (ver la doc del modulo).
     * `alto`: el de la hoja en esas unidades (`1400 * alto / ancho` de la
     * pagina tal como se ve). Si no hay tinta, nace vacia y no se escribe
     * nada hasta que se anote. Guardar con [`EditorLienzo::guardar`] (fuera
     * del hilo principal) escribe la tinta y su marco.
     */
    func anotarHoja(documento: String, pagina: UInt32, alto: Float) throws  -> EditorLienzo
    
    /**
     * Adonde va lo anotado de `documento`.
     */
    func dondeAnota(documento: String)  -> DondeAnota
    
    /**
     * **Guarda lo que se recuerda**: aumento y pagina junto al documento
     * (de esta pantalla), y marcadores y espacios donde viajan (los del PDF
     * de un adjunto o de un proyecto). Solo se escribe lo que cambia.
     *
     * `altos`: el alto de cada hoja en unidades de la tinta. Si los espacios
     * cambian, a la tinta del chat que aun no tiene marco se le apunta antes
     * el de la regla de ahora (`fijar_lo_viejo`), para que no se corra.
     */
    func guardarLecturaDeDocumento(documento: String, lectura: LecturaDocumento, altos: [Float]) throws 
    
    /**
     * **Que hojas tienen tinta** de las `paginas` primeras (sin leerlas:
     * solo si su fichero esta). Para no abrir un editor por hoja vacia.
     */
    func hojasConTinta(documento: String, paginas: UInt32)  -> [UInt32]
    
    /**
     * **Lo que se recuerda de un documento** (`documento`: su ruta en este
     * Mac, la de [`Nucleo::ruta_absoluta`] si es un adjunto): aumento,
     * pagina, espacios para anotar y marcadores, y adonde va lo anotado.
     */
    func lecturaDeDocumento(documento: String)  -> LecturaDocumento
    
    /**
     * **Un lienzo nuevo en un chat**: el `.excalidraw` vacio en
     * `lienzos/<codigo>.excalidraw` y su mensaje `DIBUJO` al final del
     * cuaderno, como `ventana_chat::escribir_lienzo` de Windows. Se abre
     * despues con [`Nucleo::editar_lienzo`] y la `referencia` del mensaje.
     */
    func crearLienzo(chat: String, nombre: String?) throws  -> MensajeChat
    
    /**
     * **Abre para editar** el lienzo `dibujo` de un chat (la `referencia`
     * de un mensaje `DIBUJO`). Sus fotos salen ya con la ruta absoluta.
     */
    func editarLienzo(chat: String, dibujo: String) throws  -> EditorLienzo
    
    /**
     * **Abre la puerta para enviar** `rutas` con un codigo nuevo de seis
     * cifras, en un puerto que da el sistema (IPv6 con IPv4 dentro).
     */
    func abrirEnvio(rutas: [String]) throws  -> PuertaEnvio
    
    /**
     * Lo que esta delante, como lo dejo [`Nucleo::poner_al_frente`].
     */
    func alFrente()  -> FrenteMac
    
    /**
     * **«Enviar a…» un aparato del grupo**: manda `rutas` (ficheros) a lo
     * que el aparato de `host:puerto` tenga delante, por el canal del
     * grupo, uno detras de otro en la misma conexion. Devuelve como quedo
     * cada uno: uno que el otro no acepta (lienzo delante y no es foto) no
     * corta los demas; si se corta la red, los que faltan salen con error.
     */
    func enviarAAparato(host: String, puerto: UInt16, rutas: [String]) throws  -> [EnvioSuelto]
    
    /**
     * **Espera para recibir** («Recibir por Wi-Fi»): un codigo nuevo de
     * seis cifras y un puerto; quien envia teclea el codigo (o lo ve en el
     * QR) y llama. Se atiende desde un hilo de Swift con
     * [`PuertaRecibir::atender`].
     */
    func esperarEnvios() throws  -> PuertaRecibir
    
    /**
     * **Manda `rutas` a quien espera para recibir** en `host:puerto` con su
     * `codigo` (el que ensena su pantalla). Bloquea hasta terminar.
     */
    func mandarAQuienEspera(host: String, puerto: UInt16, codigo: String, rutas: [String]) throws  -> FinEnvio
    
    /**
     * **Lo que esta delante ahora** (lo llama Swift al abrir o cerrar un
     * chat o un lienzo): a donde va un archivo suelto que llegue.
     */
    func ponerAlFrente(frente: FrenteMac) 
    
    /**
     * **Recibe de quien envia y espera** en `host:puerto` con su `codigo`:
     * trae lo que ofrece y lo pone en su sitio (proyectos a la lista, lo
     * demas a «Mensajes guardados»). Teclear el codigo es aceptar.
     */
    func recibirEnvio(host: String, puerto: UInt16, codigo: String) throws  -> [RecibidoEnvio]
    
    /**
     * **Borra capturas**: a la papelera de PixPin (`papelera/capturas/`),
     * sin preguntar (se deshace con [`Nucleo::devolver_capturas`]), y se
     * olvida si estaban conservadas o prorrogadas (su nombre queda libre).
     * Lo que se pudo mover se devuelve aunque alguna fallara; si fallo
     * alguna y no se movio ninguna, es un error.
     */
    func borrarCapturas(nombres: [String]) throws  -> [CapturaBorrada]
    
    /**
     * **Las capturas que ya caducaron** con el plazo `dias` (el ajuste
     * `[capturas] dias_caducidad`; 0 = nunca): las mismas reglas que el
     * barrendero de Windows. No mueve nada: Swift las lleva a la Papelera
     * del Mac (`FileManager.trashItem`) y luego llama a
     * [`Nucleo::olvidar_capturas_ausentes`]. La carpeta se lee de la cache
     * si no cambio.
     */
    func capturasCaducadas(dias: Int64)  -> [CapturaCaducada]
    
    /**
     * La carpeta de las capturas (`<datos>/capturas`), donde Swift guarda
     * las nuevas y vigila con FSEvents.
     */
    func carpetaCapturas()  -> String
    
    /**
     * **Conserva una captura**: entra en «Mensajes guardados» como una foto
     * mas (se copia, como al adjuntar; de ahi viaja al movil) y se apunta
     * en `conservadas` para que no caduque. Devuelve el mensaje nuevo. Una
     * ya conservada da error de argumento («ya estaba conservada»), como el
     * aviso de Windows: no se manda dos veces al chat.
     */
    func conservarCaptura(nombre: String) throws  -> MensajeChat
    
    /**
     * **Deshace un borrado**: cada una vuelve a `capturas/` (si su nombre
     * sigue libre) con lo que tenia apuntado. Devuelve cuantas volvieron.
     */
    func devolverCapturas(borradas: [CapturaBorrada]) throws  -> UInt32
    
    /**
     * **Una pagina de la galeria**, de la mas nueva a la mas vieja: `desde`
     * es la posicion de la primera (0 la mas nueva) y `cuantos` el largo
     * (hasta [`TOPE_DE_PAGINA_GALERIA`]). `dias` es el plazo del ajuste
     * («dias hasta borrar», 0 = nunca) y `desfase_ms` el del huso de quien
     * mira (para contar los dias que quedan por dias de calendario).
     */
    func galeria(desde: UInt64, cuantos: UInt32, dias: Int64, desfaseMs: Int64) throws  -> PaginaGaleria
    
    /**
     * **Tras barrer**: olvida las conservadas y prorrogadas cuyo fichero
     * ya no esta (el numero de `captura-NNNN` se reutiliza: una nueva con
     * el nombre de una conservada que se fue no tiene por que quedarse
     * para siempre), como el final de `caducidad_capturas::barrer`. Suelta
     * la lista de la cache. Devuelve cuantos nombres se olvidaron; si no
     * sobra ninguno, no se escribe el registro.
     */
    func olvidarCapturasAusentes() throws  -> UInt32
    
    /**
     * **«Dar 7 dias mas»**: siete dias despues de la fecha que tenia (o de
     * ahora, si ya habia pasado). Con fecha acordada con el grupo se mueve
     * esa; si no, va a `prorrogadas`. Devuelve la fecha nueva, o `None` si
     * no se va (conservada o caducidad apagada).
     */
    func prorrogarCaptura(nombre: String, dias: Int64) throws  -> Int64?
    
    /**
     * **Abre la hoja de calculo de un mensaje**: una tabla del PC (`MINIAPP`
     * tabla) o del movil (`TABLA`). `NoExiste` si el mensaje no esta o su
     * fichero aun no llego (mejor no abrir que abrir en blanco y guardar
     * encima); `Argumento` si no es una tabla.
     */
    func abrirHojaDeCalculo(chat: String, mensaje: String) throws  -> HojaDeCalculo
    
    /**
     * **Una tabla nueva en un chat**: un mensaje `MINIAPP` tabla con la
     * tabla vacia, como la crea Windows. Se abre despues con
     * [`Nucleo::abrir_hoja_de_calculo`].
     */
    func crearTabla(chat: String, nombre: String) throws  -> MensajeChat
    
    /**
     * Si el mensaje es una hoja de calculo que se abre con
     * [`Nucleo::abrir_hoja_de_calculo`] (sin leer su tabla).
     */
    func esHojaDeCalculo(chat: String, mensaje: String)  -> Bool
    
    /**
     * **Borra una leccion** como borra el chat: su mensaje y los de sus
     * fotos y audios salen del cuaderno con su marca de borrado (para que
     * no vuelvan del otro aparato) y sus archivos se van.
     */
    func borrarLeccion(id: String) throws 
    
    /**
     * **Guarda una leccion**: la primera vez crea su archivo y su mensaje
     * en el chat; las siguientes reescriben el archivo y ponen al dia el
     * resumen del mensaje. Lo que no se toca aqui (repeticiones, repaso,
     * adjuntos, campos de una version mas nueva) se conserva.
     */
    func guardarLeccion(editada: LeccionEditada) throws  -> FichaLeccion
    
    /**
     * Una leccion por su id.
     */
    func leccion(id: String) throws  -> FichaLeccion
    
    /**
     * **Una pagina de lecciones** con el filtro dado: `desde` es la
     * posicion de la primera y `cuantas` el largo (hasta
     * [`TOPE_DE_PAGINA`]).
     */
    func lecciones(filtro: FiltroLecciones, desde: UInt64, cuantas: UInt32) throws  -> PaginaLecciones
    
    /**
     * Lo que propone el etiquetador para lo escrito (etiquetas, area,
     * tipo, causas y gravedad), con lo que uno suele etiquetar.
     */
    func proponerLeccion(texto: String, quitadas: [String])  -> PropuestaLeccion
    
    /**
     * Apunta como fue el repaso (o que volvio a pasar) y la guarda.
     */
    func repasarLeccion(id: String, nota: NotaRepaso) throws  -> FichaLeccion
    
    /**
     * El lienzo `dibujo` de un chat (`proyectos/<chat>/lienzos/<dibujo>.excalidraw`,
     * lo que apunta la `referencia` de un mensaje `DIBUJO`).
     */
    func abrirLienzo(chat: String, dibujo: String) throws  -> Lienzo
    
    /**
     * **Crea una mini-app en un chat**: un mensaje `MINIAPP` con su
     * documento de nacer, como el boton «+» del movil (`pedidos::nueva_lista`
     * en Windows). Sube el chat en la lista.
     */
    func crearMiniapp(chat: String, miniapp: String, titulo: String, moneda: String) throws  -> MensajeChat
    
    /**
     * El documento de una mini-app tal como esta ahora en el chat (por si
     * llego cambiado del movil).
     */
    func documentoMiniapp(chat: String, mensaje: String) throws  -> String
    
    /**
     * **Guarda el documento** de una mini-app en su mensaje. `anterior` es
     * el documento sobre el que se hizo el cambio: si el del chat ya no es
     * ese (llego otro del movil), no se toca nada y se devuelve `false`
     * (hay que releer con [`Nucleo::documento_miniapp`]).
     */
    func guardarMiniapp(chat: String, mensaje: String, anterior: String, documento: String) throws  -> Bool
    
    /**
     * **Guarda el texto de una nota** (`mensaje`: el id de un `NOTA`) donde
     * la tenga, como `notas_md::guardar` de Windows: en su linea del
     * cuaderno (lo demas de la linea queda como estaba) y, si el proyecto
     * tiene una hoja `nota` con el mismo codigo unico (una nota del movil),
     * tambien en ella y en su copia `notas/<id>.md`. Sube el `tocado` del
     * chat. Devuelve el mensaje como quedo. Bloqueante.
     */
    func editarNota(chat: String, mensaje: String, texto: String) throws  -> MensajeChat
    
    /**
     * **Abre un plano DWG o DXF** (por capas). Bloquea (un plano grande
     * tarda segundos): Swift lo llama desde una `Task` de prioridad
     * `.userInitiated`.
     */
    func abrirPlano(ruta: String) throws  -> Plano
    
    /**
     * **El anuncio de Bonjour de este aparato**, o `None` si no esta en
     * ningun grupo (sin grupo no se anuncia: nadie sabria que hacer con el).
     * Hay que volver a pedirlo al crear un grupo o unirse a uno, que cambian
     * la etiqueta y la letra.
     *
     * La primera vez por codigo cuesta las 60 000 vueltas de PBKDF2 de la
     * etiqueta (luego se recuerda): no llamarlo en el hilo de la interfaz.
     */
    func anuncio() throws  -> AnuncioBonjour?
    
    /**
     * **Lo que hay que anunciar para dejarse encontrar**, como la presencia
     * de Windows: con grupo, [`Nucleo::anuncio`]; **sin grupo pero dentro
     * de algun chat compartido con personas**, el mismo anuncio sin `g` (y
     * con la etiqueta vacia): las personas de esos chats llaman aqui y
     * buscan por el `id`, y sin `g` no sale como aparato propio de nadie.
     * `None` si no hay por que escuchar.
     */
    func anuncioDePresencia() throws  -> AnuncioBonjour?
    
    /**
     * Crea un grupo nuevo con este aparato dentro (letra `a`) y devuelve su
     * codigo, para ensenarlo y que los demas se unan. Como `crearGrupo` de
     * Android.
     */
    func crearGrupo() throws  -> String
    
    /**
     * Escucha en `puerto` (0: el que de el sistema; el de siempre es
     * 47474, [`puerto_preferido`]) para que otro aparato sincronice con
     * este, se una a su grupo, le mande un archivo suelto o sea una persona
     * de un chat compartido. Por IPv6 con IPv4 dentro si se puede; si no,
     * solo IPv4. Si el puerto pedido esta tomado, falla: quien llama vuelve
     * a probar con 0, como Windows.
     */
    func escuchar(puerto: UInt16) throws  -> Escucha
    
    /**
     * La etiqueta del grupo de este aparato (el `g` que anuncian los
     * suyos), o `None` sin grupo. Cuesta lo mismo que [`Nucleo::anuncio`].
     */
    func etiqueta() throws  -> String?
    
    /**
     * **Una vuelta de sincronizar** con el aparato de `host:puerto`, del
     * mismo grupo: sin preguntar, con lo elegido la ultima vez con el (o
     * todo la primera), y sin borrar ningun proyecto, como «con todos» de
     * Windows. Lleva tambien **la galeria de capturas** detras de los chats
     * y respeta «lo mio manda» de `pixpinmax.toml`. `host` puede ser IPv4,
     * IPv6 (con su interfaz si es de enlace local: `fe80::1%en0`) o un
     * nombre. Bloquea hasta terminar.
     */
    func sincronizarCon(host: String, puerto: UInt16) throws  -> ResumenSincro
    
    /**
     * **Se une al grupo** de otro aparato que escucha en `host:puerto`, con
     * el `codigo` que ensena el. Sale con su letra; los chats se pasan
     * despues con [`Nucleo::sincronizar_con`], como en Windows.
     */
    func unirseAGrupo(host: String, puerto: UInt16, codigo: String) throws  -> InfoAparato
    
    /**
     * **Apunta una tarea en el Inbox** de «Mensajes guardados» con la
