        /**
         * `g`, `id`, `l`, `n`, en ese orden.
         */txt: [ParTxt], 
        /**
         * La etiqueta del grupo (el valor de `g`), para comparar con lo que
         * anuncian los demas.
         */etiqueta: String, 
        /**
         * El id de este aparato (el valor de `id`), para no verse a si mismo.
         */id: String) {
        self.instancia = instancia
        self.tipo = tipo
        self.txt = txt
