/**
 * Un mensaje, con lo que hace falta para pintar su burbuja.
 */
public struct MensajeChat: Equatable, Hashable {
    public var id: String
    /**
     * Milisegundos desde 1970.
     */
    public var cuando: Int64
    /**
     * `NOTA`, `IMAGEN`, `ARCHIVO`, `VOZ`, `DIBUJO`, `PAGINA`, `PROYECTO`,
     * `MINIAPP` o la palabra que traiga una version mas nueva del movil.
     */
    public var clase: String
    public var texto: String
    public var nombre: String
    /**
     * Fichero del mensaje, relativo a la carpeta del chat.
     */
    public var ruta: String?
    public var bytes: Int64
    /**
     * Lo que se ensena en una linea (la transcripcion de una nota de voz,
     * el texto o el nombre).
     */
    public var resumen: String
    /**
     * `47·K7Q2`, `47a` o nada.
     */
    public var codigoChat: String?
    public var respondeA: String?
    public var emoji: String?
    public var fijado: Bool
    /**
     * El dibujo o la hoja a la que apunta (un `DIBUJO`, una `PAGINA`).
     */
    public var referencia: String?
    public var pagina: UInt32?
    /**
     * Lo que dura el audio de una nota de voz, en milisegundos (0 si no es
     * una o no se sabe).
     */
    public var duracionMs: Int64
    /**
     * El texto de una nota de voz con sus minutos (`[0:05] lo dicho`), si
     * ya se paso a texto. Ver [`crate::voz`].
     */
    public var transcripcion: String?
    /**
     * Los picos de la onda de una nota de voz: enteros de 0 a 32767, como
     * mucho 256 (el campo `picos` del movil). Vacio si no los trae.
     */
    public var picos: [Int32]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, 
        /**
         * Milisegundos desde 1970.
         */cuando: Int64, 
        /**
         * `NOTA`, `IMAGEN`, `ARCHIVO`, `VOZ`, `DIBUJO`, `PAGINA`, `PROYECTO`,
         * `MINIAPP` o la palabra que traiga una version mas nueva del movil.
         */clase: String, texto: String, nombre: String, 
        /**
         * Fichero del mensaje, relativo a la carpeta del chat.
         */ruta: String?, bytes: Int64, 
        /**
         * Lo que se ensena en una linea (la transcripcion de una nota de voz,
         * el texto o el nombre).
         */resumen: String, 
        /**
         * `47·K7Q2`, `47a` o nada.
         */codigoChat: String?, respondeA: String?, emoji: String?, fijado: Bool, 
        /**
         * El dibujo o la hoja a la que apunta (un `DIBUJO`, una `PAGINA`).
         */referencia: String?, pagina: UInt32?, 
        /**
         * Lo que dura el audio de una nota de voz, en milisegundos (0 si no es
         * una o no se sabe).
         */duracionMs: Int64, 
        /**
         * El texto de una nota de voz con sus minutos (`[0:05] lo dicho`), si
         * ya se paso a texto. Ver [`crate::voz`].
         */transcripcion: String?, 
        /**
         * Los picos de la onda de una nota de voz: enteros de 0 a 32767, como
         * mucho 256 (el campo `picos` del movil). Vacio si no los trae.
         */picos: [Int32]) {
        self.id = id
        self.cuando = cuando
        self.clase = clase
        self.texto = texto
        self.nombre = nombre
        self.ruta = ruta
        self.bytes = bytes
        self.resumen = resumen
        self.codigoChat = codigoChat
        self.respondeA = respondeA
        self.emoji = emoji
        self.fijado = fijado
        self.referencia = referencia
        self.pagina = pagina
        self.duracionMs = duracionMs
        self.transcripcion = transcripcion
        self.picos = picos
    }

    

    
}

